// Generated by the hydrolysis `hwui::kotlin` test from `src/hwui/protocol.rs`
// and `src/hwui/text/wire.rs`, the single source of the wire. Never edited
// and never committed: Gradle regenerates it under `build/` with the
// contract scenes.
package dev.waterui.hydrolysis.hwui

import android.graphics.BlendMode

/**
 * The HWUI command-buffer wire format. A frame is little-endian 32-bit
 * words: a header of [MAGIC], the frame sequence and the byte length, then
 * records of one word (`u16` opcode low, `u16` payload words high) and the
 * payload.
 */
object Protocol {
{%- for constant in protocol %}
{%- if !constant.doc.is_empty() %}
    /** {{ constant.doc }} */
{%- endif %}
    const val {{ constant.name }}: {{ constant.ty }} = {{ constant.value }}
{%- endfor %}

    /** [fixedWords] of an op whose length follows from its counts. */
    const val VARIABLE: Int = -1

    /** [fixedWords] of an opcode the protocol does not define. */
    const val UNKNOWN: Int = -2
{% for op in ops %}
    const val {{ op.constant }}: Int = {{ op.code }}
{%- endfor %}

    /** The payload words of a fixed-size op, [VARIABLE] or [UNKNOWN]. */
    fun fixedWords(op: Int): Int =
        when (op) {
{%- for op in ops %}
            {{ op.constant }} -> {{ op.words }}
{%- endfor %}
            else -> UNKNOWN
        }

    /** The op's name in the contract test's event log. */
    fun name(op: Int): String =
        when (op) {
{%- for op in ops %}
            {{ op.constant }} -> "{{ op.name }}"
{%- endfor %}
            else -> String.format("0x%04x", op)
        }
}
{% for object in objects %}
/** {{ object.doc }} */
object {{ object.name }} {
{%- for constant in object.constants %}
{%- if !constant.doc.is_empty() %}
    /** {{ constant.doc }} */
{%- endif %}
    const val {{ constant.name }}: {{ constant.ty }} = {{ constant.value }}
{%- endfor %}
{%- if object.name == "Verb" %}

    /** The points `verb` consumes, or -1 for an unknown verb. */
    fun points(verb: Int): Int =
        when (verb) {
            MOVE, LINE -> 1
            QUAD -> 2
            CUBIC -> 3
            CLOSE -> 0
            else -> -1
        }
{%- endif %}
{%- if object.name == "BlendCode" %}

    /** The `BlendMode` named by `code`. */
    fun mode(code: Int): BlendMode =
        when (code) {
{%- for constant in object.constants %}
            {{ constant.name }} -> BlendMode.{{ constant.name }}
{%- endfor %}
            else -> throw CommandBufferException("HWUI replay: blend code $code is unknown")
        }
{%- endif %}
}
{% endfor %}
/**
 * The text wire between the Rust text engine and [HwuiTextProvider]. A
 * style run is [SPAN_WORDS] ints over UTF-16 offsets, its colours
 * `ColorLong`s in two words, low then high. Family lists cross as one string
 * each, names joined by [FAMILY_SEPARATOR]. A shaping reply is the layout
 * width, height, ink top and ink bottom, then [LINE_WORDS] floats per line:
 * advance, line height, baseline, ink left, ink right. An ink span without
 * ink carries `+inf, -inf`.
 */
object TextWire {
{%- for constant in text %}
{%- if !constant.doc.is_empty() %}
    /** {{ constant.doc }} */
{%- endif %}
    const val {{ constant.name }}: {{ constant.ty }} = {{ constant.value }}
{%- endfor %}

    /** The `ColorLong` at `spans[at]` (low word) and `spans[at + 1]` (high word). */
    fun colorLong(spans: IntArray, at: Int): Long = (spans[at + 1].toLong() shl 32) or (spans[at].toLong() and 0xffff_ffffL)

    /** A position: the offset shifted left once, the low bit set upstream. */
    fun packPosition(offset: Int, upstream: Boolean): Long = (offset.toLong() shl 1) or (if (upstream) 1L else 0L)

    /** A range: the start in the high word, the end in the low word. */
    fun packRange(start: Int, end: Int): Long = (start.toLong() shl 32) or (end.toLong() and 0xffff_ffffL)
}
